import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";

import {
  DEFAULT_LEEWAY_SECONDS, MAX_ATOMIC, MAX_LEEWAY_SECONDS, MAX_TOKEN_LENGTH, MIN_ATOMIC,
  MemoryReplayGuard, verifyPaymentContext
} from "../src/payment-context.mjs";
import { createPaymentKeyResolver } from "../src/payment-keys.mjs";

// Shared with the Python validator (tests/test_x402_payment_context_vectors.py).
// Generated by tools/x402_payment_context_vectors.py with test-only keys.
const document = JSON.parse(await readFile(
  new URL("../../../tests/vectors/x402-payment-context.v1.json", import.meta.url), "utf8"
));
// Each vector key set is served through the production resolver (an injected
// fetch of the pinned URL), so it passes the same key-set checks as live keys.
const keySets = Object.fromEntries(Object.entries(document.jwks).map(([name, jwks]) => [
  name,
  createPaymentKeyResolver({
    now: () => 0,
    fetch: async () => new Response(JSON.stringify(jwks), {
      headers: { "content-type": "application/json", "cache-control": "max-age=3600" }
    })
  })
]));

async function outcome(vector, extra = {}) {
  try {
    const verified = await verifyPaymentContext(vector.token, {
      keys: keySets[vector.jwks],
      expectedAudience: vector.expected_audience,
      scheme: vector.scheme,
      expectedAmount: vector.expected_amount,
      now: vector.now,
      leewaySeconds: vector.leeway,
      requestUrl: vector.request_url,
      ...extra
    });
    return { verified, result: { valid: true, amount: verified.amount } };
  } catch (error) {
    assert.equal(error.name, "PaymentContextError", `${vector.name}: ${error.stack}`);
    return { result: { valid: false, reason: error.reason } };
  }
}

test("vector contract constants match this module", () => {
  assert.deepEqual(document.contract, {
    default_leeway_seconds: DEFAULT_LEEWAY_SECONDS,
    max_leeway_seconds: MAX_LEEWAY_SECONDS,
    min_atomic: MIN_ATOMIC,
    max_atomic: MAX_ATOMIC,
    max_token_length: MAX_TOKEN_LENGTH
  });
  assert.ok(document.vectors.length >= 90);
});

for (const vector of document.vectors) {
  test(`vector ${vector.name}`, async () => {
    const { verified, result } = await outcome(vector);
    assert.deepEqual(result, vector.result);
    if (verified) {
      assert.equal(verified.settlement_evidence, false);
      assert.match(verified.token_sha256, /^[0-9a-f]{64}$/);
    }
  });
}

test("the replay guard accepts a context once, then refuses it until it expires", async () => {
  const vector = document.vectors.find(({ name }) => name === "exact-valid");
  const replayGuard = new MemoryReplayGuard();
  assert.deepEqual((await outcome(vector, { replayGuard })).result, vector.result);
  assert.deepEqual((await outcome(vector, { replayGuard })).result, { valid: false, reason: "REPLAYED" });
  const rotated = document.vectors.find(({ name }) => name === "rotated-key-valid");
  assert.deepEqual((await outcome(rotated, { replayGuard })).result, rotated.result);
  // A later request at exp + leeway can no longer validate, so the entry is pruned.
  const pruned = replayGuard.checkAndRemember("probe", { expiresAt: Infinity, now: 1770000125 });
  assert.equal(pruned, null);
});

test("a full replay guard refuses new contexts instead of forgetting live ones", async () => {
  const vector = document.vectors.find(({ name }) => name === "exact-valid");
  const replayGuard = new MemoryReplayGuard({ maxEntries: 1 });
  assert.equal(replayGuard.checkAndRemember("other", { expiresAt: vector.now + 60, now: vector.now }), null);
  assert.deepEqual((await outcome(vector, { replayGuard })).result, { valid: false, reason: "REPLAY_CACHE_FULL" });
  assert.throws(() => new MemoryReplayGuard({ maxEntries: 0 }), TypeError);
});
